```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# 0. TOP-LEVEL CLASSES
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Can focus on an individual learner, a learning community, a course, a program, an institution, or an educational system (granularity)." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination", "exam", "evaluation" ;
  rdfs:comment "Assessment is often used interchangeably with 'test', but assessment is not limited to tests. A test/examination is an educational assessment intended to measure knowledge, skill, aptitude, physical fitness or classification." .

#################################################################
# 1. GRANULARITY
#################################################################

ea:GranularityLevel a owl:Class .
ea:IndividualLearnerLevel   rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityLevel   rdfs:subClassOf ea:GranularityLevel .
ea:CourseLevel              rdfs:subClassOf ea:GranularityLevel .
ea:AcademicProgramLevel     rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionLevel         rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemLevel   rdfs:subClassOf ea:GranularityLevel .

ea:GranularityLevel owl:disjointUnionOf
  ( ea:IndividualLearnerLevel ea:LearningCommunityLevel ea:CourseLevel
    ea:AcademicProgramLevel ea:InstitutionLevel ea:EducationalSystemLevel ) .

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel .

#################################################################
# 2. PURPOSE AXIS: Placement / Formative / Summative / Diagnostic
#################################################################

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose  rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose  rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose  rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment", "formative evaluation" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  skos:altLabel "assessment of learning", "summative evaluation" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a coordinate category alongside placement/formative/summative (hence modeled in the disjoint PurposeCategory partition), while another passage states 'A common form of formative assessment is diagnostic assessment', which is modeled here as rdfs:subClassOf ea:FormativeAssessment. Both claims are encoded even though, combined with the disjointness axiom below, this renders ea:DiagnosticAssessment unsatisfiable -- a faithful reflection of the source conflict." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Forward-looking assessment asks those being assessed to consider themselves in hypothetical future situations." .
ea:BackwardLookingAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .
[] a owl:AllDisjointClasses ; owl:members ( ea:ForwardLookingAssessment ea:BackwardLookingAssessment ) .

#################################################################
# 3. OBJECTIVE / SUBJECTIVE AXIS
#################################################################

ea:ResponseTypeCategory a owl:Class .
ea:ObjectiveResponseType rdfs:subClassOf ea:ResponseTypeCategory .
ea:SubjectiveResponseType rdfs:subClassOf ea:ResponseTypeCategory .
ea:ResponseTypeCategory owl:disjointUnionOf ( ea:ObjectiveResponseType ea:SubjectiveResponseType ) .

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ResponseTypeCategory .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer; well suited to computerized/online assessment." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer. Some argue the objective/subjective distinction is neither useful nor accurate, since all assessments carry inherent biases." .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveAssessment ea:SubjectiveAssessment ) .

#################################################################
# 4. REFERENCING AXIS: Criterion / Norm / Ipsative
#################################################################

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencing rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing      rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing  rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria, e.g. the driving test." .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment", "grading on the curve" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:comment "Relative to the student body taking it, e.g. the IQ test." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time or across domains within the same student." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

#################################################################
# 5. FORMALITY AXIS
#################################################################

ea:FormalityCategory a owl:Class .
ea:FormalCategory rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document, given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Does not contribute to a student's final grade; may include observation, checklists, rating scales, portfolios." .

[] a owl:AllDisjointClasses ; owl:members ( ea:FormalAssessment ea:InformalAssessment ) .

#################################################################
# 6. LOCUS AXIS: Internal / External
#################################################################

ea:LocusCategory a owl:Class .
ea:InternalLocus rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:comment "Set by a governing body and marked by unbiased personnel." .

[] a owl:AllDisjointClasses ; owl:members ( ea:InternalAssessment ea:ExternalAssessment ) .

#################################################################
# 7. STANDARDIZATION AXIS (on Test)
#################################################################

ea:StandardizationCategory a owl:Class .
ea:StandardizedManner    rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedManner rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedManner ea:NonStandardizedManner ) .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedManner ] ) ] ;
  rdfs:comment "Administered and scored in a consistent/standard manner for all test takers. Need not be high-stakes, time-limited, multiple-choice, or academic." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedManner ] ) ] ;
  rdfs:comment "Flexible in scope and format, variable in difficulty." .

[] a owl:AllDisjointClasses ; owl:members ( ea:StandardizedTest ea:NonStandardizedTest ) .

ea:AchievementTest        rdfs:subClassOf ea:StandardizedTest, ea:BackwardLookingAssessment .
ea:AptitudeTest           rdfs:subClassOf ea:StandardizedTest, ea:ForwardLookingAssessment .
ea:CollegeAdmissionsTest  rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest      rdfs:subClassOf ea:StandardizedTest .

#################################################################
# 8. STAKES AXIS (on Test)
#################################################################

ea:StakesCategory a owl:Class .
ea:HighStakesCategory rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory  rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance / important consequences for the test taker." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:HighStakesTest ea:LowStakesTest ) .

#################################################################
# 9. REFERENCING-BASED TEST SUBCLASSES + COMPETITIVE EXAMINATION
#################################################################

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:subClassOf ea:NormReferencedAssessment .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT", "mastery test" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:subClassOf ea:CriterionReferencedAssessment .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedTest ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The criterion itself is the subject-matter domain, not the cut score; the cut score is merely the threshold applied to it." .

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     ea:Test
     [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
     [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "Candidates are ranked according to grade/percentile and top rankers selected; norm-referenced, high-stakes." .

#################################################################
# 10. PERFORMANCE / AUTHENTIC / CONTINUOUS / COMPLEX ASSESSMENT
#################################################################

ea:PerformanceAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  skos:altLabel "performance-based assessment" ;
  rdfs:comment "Similar to summative assessment in focusing on achievement; requires students to create, produce, or do something, often with real-world application." .

ea:ProductAssessment rdfs:subClassOf ea:PerformanceAssessment .
ea:PerformanceDemonstrationAssessment rdfs:subClassOf ea:PerformanceAssessment .
[] a owl:AllDisjointClasses ; owl:members ( ea:ProductAssessment ea:PerformanceDemonstrationAssessment ) .

ea:AuthenticAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside of school. Corpus states 'performance assessments may also be called authentic assessments', suggesting near-synonymy; however, both appear as distinct coordinate entries in the enumerated 'assessment types' list, so they are kept as distinct classes with this noted overlap." ;
  skos:closeMatch ea:PerformanceAssessment .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often used as an alternative to a final-examination system; often includes formative assessment." .

ea:hasComponent a owl:ObjectProperty ;
  rdfs:domain ea:ContinuousAssessment ;
  rdfs:range ea:FormativeAssessment .

ea:ExpertExaminer a owl:Class .

ea:hasExaminer a owl:ObjectProperty ;
  rdfs:domain ea:ComplexAssessment ;
  rdfs:range ea:ExpertExaminer .

ea:ComplexAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
    [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ] ) ] ;
  rdfs:comment "An assessment that requires a rubric and an expert examiner, e.g. thesis, funding proposal." .

#################################################################
# 11. TEST ITEM FORMATS
#################################################################

ea:TestItem a owl:Class ; rdfs:label "TestItem" .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:ObjectiveItem a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] .

ea:SubjectiveItem a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] .

ea:TrueFalseItem      rdfs:subClassOf ea:TestItem, ea:ObjectiveItem .
ea:MultipleResponseItem rdfs:subClassOf ea:TestItem, ea:ObjectiveItem .
ea:MatchingItem       rdfs:subClassOf ea:TestItem, ea:ObjectiveItem .
ea:FillInTheBlankItem rdfs:subClassOf ea:TestItem .
ea:ShortAnswerItem    rdfs:subClassOf ea:TestItem .
ea:ExtendedResponseItem rdfs:subClassOf ea:TestItem, ea:SubjectiveItem .
ea:EssayItem a owl:Class ;
  skos:altLabel "free response question", "FRQ" ;
  rdfs:subClassOf ea:ExtendedResponseItem .

ea:Stem a owl:Class .
ea:AnswerOption a owl:Class .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
[] a owl:AllDisjointClasses ; owl:members ( ea:Key ea:Distractor ) .

ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Stem .
ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Key .
ea:hasDistractor a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Distractor .

ea:MultipleChoiceItem a owl:Class ;
  skos:altLabel "MCQ", "objective response item" ;
  rdfs:subClassOf ea:TestItem, ea:ObjectiveItem ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ;
      owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ;
      owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct, in contrast with multiple-choice items." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:MultipleChoiceItem ea:TrueFalseItem ea:MultipleResponseItem
                ea:MatchingItem ea:FillInTheBlankItem ea:ExtendedResponseItem ) .

#################################################################
# 12. TEST ADMINISTRATION MEDIUM
#################################################################

ea:WrittenTest        rdfs:subClassOf ea:Test .
ea:OralTest           rdfs:subClassOf ea:Test .
ea:PracticalTest      rdfs:subClassOf ea:Test .
ea:ComputerBasedTest  rdfs:subClassOf ea:Test ; skos:altLabel "on-screen test" .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:WrittenTest ea:OralTest ea:PracticalTest ea:ComputerBasedTest ) .

ea:MidtermExam rdfs:subClassOf ea:Test ;
  rdfs:comment "Given near the middle of an academic term; a type of formative or summative assessment (disjunctive claim kept as comment rather than a strict subClassOf of either)." .
ea:FinalExam   rdfs:subClassOf ea:Test .
ea:Quiz        rdfs:subClassOf ea:Test, ea:LowStakesTest, ea:FormativeAssessment ;
  rdfs:comment "A brief assessment, usually not weighted heavily; commonly a formative, low-stakes assessment." .

#################################################################
# 13. RUBRICS AND GRADING METHODS
#################################################################

ea:Rubric a owl:Class ;
  skos:altLabel "scoring guide" ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses (Popham)." .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:HolisticRubric  rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric  rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "A developmental rubric is described as a subset of analytical rubrics." .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticRubric ea:AnalyticRubric ) .

ea:GradingMethod a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole; contrasts with analytic grading." .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Takes more factors (criteria) into account when assigning a grade; criterion-by-criterion judgments." .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:usesRubric a owl:ObjectProperty ;
  rdfs:domain ea:GradingMethod ; rdfs:range ea:Rubric .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "TENSION: trait-informed scoring 'comes close to' analytic scoring methods (independent per-trait scores summed to a final mark) yet the corpus states it 'remains holistic at heart' since raters take all traits into account before giving a single final score. Modeled as a subclass of HolisticGrading, with this comment flagging its analytic-like character." .

#################################################################
# 14. VALIDITY
#################################################################

ea:QualityAttribute a owl:Class .
ea:Validity a owl:Class ; rdfs:subClassOf ea:QualityAttribute ;
  rdfs:comment "The degree to which an assessment measures what it is supposed to measure." .
ea:Reliability a owl:Class ; rdfs:subClassOf ea:QualityAttribute ;
  rdfs:comment "The consistency of an assessment; a valid measure must be reliable, but a reliable measure need not be valid." .

ea:hasValidityEvidence a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Validity .
ea:hasReliabilityEvidence a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .

ea:ContentValidity      rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity    rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity    rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity rdfs:subClassOf ea:Validity .
ea:FaceValidity         rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
                ea:ConsequentialValidity ea:FaceValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: the corpus enumerates content/criterion/construct validity (plus consequential and face validity) as a coordinate list of evidence categories (modeled as pairwise disjoint above), yet also states construct validity 'subsumes all other types of validity' (modeled here as subClassOf relations from Content-, Criterion- and FaceValidity into ConstructValidity). Both claims are encoded as instructed, producing an unsatisfiable set of classes." .

ea:ConvergentValidity rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity rdfs:subClassOf ea:ConstructValidity .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

ea:ValidityTimingCategory a owl:Class .
ea:SimultaneousTiming rdfs:subClassOf ea:ValidityTimingCategory .
ea:LaterTiming         rdfs:subClassOf ea:ValidityTimingCategory .
