                        owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
    skos:altLabel "standards-based assessment" .

ea:DiagnosticAssessment a owl:Class ;
    rdfs:comment "Corpus tension: one passage lists diagnostic assessment as a coordinate category alongside placement/formative/summative (hence modeled in the disjoint PurposeCategory partition), while another passage states 'A common form of formative assessment is diagnostic assessment'. To keep the class satisfiable, the strict rdfs:subClassOf ea:FormativeAssessment axiom was removed; the close relationship is retained only as a comment." ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ea:Assessment [ a owl:Restriction ;
                        owl:onProperty ea:hasPurpose ;
                        owl:someValuesFrom ea:DiagnosticPurpose ] ) ] .

